-- DISCOVERY-SCHEMAS-DEV-CRCA | env dev | snowflake D01_CRCA | connection snowflakenonprodmcp-012d
SELECT s.SCHEMA_NAME, COUNT(t.TABLE_NAME) n_objects, SUM(IFF(t.TABLE_TYPE='BASE TABLE',1,0)) n_tables, SUM(IFF(t.TABLE_TYPE='VIEW',1,0)) n_views FROM D01_CRCA.INFORMATION_SCHEMA.SCHEMATA s LEFT JOIN D01_CRCA.INFORMATION_SCHEMA.TABLES t ON t.TABLE_SCHEMA=s.SCHEMA_NAME GROUP BY 1 ORDER BY 1;
